# Test the simple column-only formula
H, W = 23, 23

def predict_col_only(r, c):
    return (c + 2) % 9

errors = []
for r in range(H):
    for c in range(W):
        val_str = grid_rows[r][c]
        if val_str != '0':
            expected = predict_col_only(r, c)
            actual = int(val_str)
            if actual != expected:
                errors.append((r, c, actual, expected))

print(f"Errors out of {H*W} cells: {len(errors)}")
print("Sample errors:")
for e in errors[:20]:
    print(e)

# Count errors per cell
error_positions = set((e[0], e[1]) for e in errors)
print(f"\nUnique error positions: {len(error_positions)}")
for rp, cp in list(error_positions)[:20]:
    print(f"Row {rp}, Col {cp}: input={grid_rows[rp][cp]}")

